                pos.setdefault(grid[r][c], []).append((r, c))

    # A compact 2x2 multicolor marker is not extended.
    allpts = [p for cells in pos.values() for p in cells]
    compact = (allpts and
               max(r for r, c in allpts) - min(r for r, c in allpts) == 1 and
               max(c for r, c in allpts) - min(c for r, c in allpts) == 1)

    if not compact:
        for color, cells in pos.items():
            if len(cells) != 2:
                continue
            (r1, c1), (r2, c2) = cells
            dr, dc = r2-r1, c2-c1
            if abs(dr) != 1 or abs(dc) != 1:
                continue
            for r, c, sr, sc in ((r1, c1, -dr, -dc), (r2, c2, dr, dc)):
                r += sr
                c += sc
                while 0 <= r < h and 0 <= c < w and out[r][c] == bg:
                    out[r][c] = color
                    r += sr
                    c += sc
