    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    pos = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                pos.setdefault(grid[r][c], []).append((r, c))

    # Extend a color along the diagonal when two of its cells establish
    # a diagonal direction. Continue outward from both ends of that pair.
    for color, cells in pos.items():
        pairs = []
        for i, (r1, c1) in enumerate(cells):
            for r2, c2 in cells[i + 1:]:
                dr, dc = r2 - r1, c2 - c1
                if abs(dr) == abs(dc) and dr != 0:
                    step = (1 if dr > 0 else -1, 1 if dc > 0 else -1)
                    pairs.append(((r1, c1), (r2, c2), step))
        if not pairs:
            continue
        # Use the longest established diagonal pair.
        (a, b, (dr, dc)) = max(
            pairs, key=lambda p: abs(p[1][0] - p[0][0])
        )
        for (r, c), sr, sc in ((a, -dr, -dc), (b, dr, dc)):
            r += sr
            c += sc
            while 0 <= r < h and 0 <= c < w and out[r][c] == bg:
                out[r][c] = color
                r += sr
                c += sc
    return out
